Add({
	kind = "topic",
	id = "gnarlpine-furbolgs",
	title = "Gnarlpine Furbolgs",
	aliases = { "Gnarlpine", "Gnarlpine tribe" },
	category = "group",
	region = "teldrassil",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Gnarlpine are a tribe of {link:furbolgs}furbolgs{/link} who lived in the hills of {link:teldrassil}Teldrassil{/link} as peaceful friends of the night elves. They have deserted their old homes and gathered under their chieftain, {link:ursal-the-mauler}Ursal the Mauler{/link}, and they now attack the very protectors they once trusted.]=],
		},
		{
			title = "The Fall of the Tribe",
			text = [=[The dryad {link:tarindrella}Tarindrella{/link} believes only the fel moss could cause such a change. {link:ursal-the-mauler}Ursal{/link} uses its powers to drive his people mad. The totems left in their abandoned camps tell more. The Gnarlpine began to dream of a great shadow that would destroy them. Their fear turned to rage, and the shadow in their dreams became their elven friends.]=],
		},
		{
			title = "Deeds of Madness",
			text = [=[• They ambushed the warden {link:gaerolas-talvethren}Gaerolas Talvethren{/link} and pillaged {link:starbreeze-village}Starbreeze Village{/link}.
